"use strict";(globalThis.webpackChunkgrc||=[]).push([[62588],{20377(e){e.exports=JSON.parse('{"citeKey":"tang2025s3roofline","slug":"tang-2025-s3-roofline-c7bd","title":"Quantifying AWS S3 I/O Performance Boundaries Using the Roofline Model","authors":["M. Tang","Z. Zhu","L. Guo","J. G. Bandy","T. Carlson","S. Neuwirth","A. Kougkas","X.-H. Sun","N. R. Tallent"],"venue":"10th International Parallel Data Systems Workshop (PDSW 2025), Proceedings of the SC \'25 Workshops","type":"Workshop","entryType":"inproceedings","date":"November, 2025","year":2025,"era":"iit","month":11,"doi":"10.1145/3731599.3767513","abstract":"High-performance computing facilities increasingly form hybrid environments that integrate cloud services. To avoid cumbersome network transfers when sharing data, a new class of storage gateways map a subset of facility storage to a cloud counterpart and automatically manage data mirroring. However, the performance characteristics of accessing AWS\'s S3 from HPC systems using different methods and patterns remains poorly understood. This paper presents a roofline-based analysis of three S3 integration approaches: NFS-mounted AWS Storage Gateway, data migration through Storage Gateway, and direct S3 API transfers. We extend I/O roofline modeling to characterize operational intensity and bandwidth ceilings across varying data sizes and access patterns. Our experimental evaluation demonstrates significant performance differences between access methods, with POSIX I/O on NFS Storage Gateway achieving up to 6.4\xd7 higher bandwidth than other approaches for large transfers. The roofline analysis reveals distinct characteristics for each method, enabling informed selection of S3 integration strategies.","hasAbstract":true,"pages":"1415\u20131423","links":{"pdf":"https://grc.iit.edu/papers/2025/tang-2025-s3-roofline-c7bd.pdf"},"tags":["I/O","Cloud Storage","AWS S3","Roofline Model","Performance Analysis"],"_projectIds":["chronolog","labios"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["iowarp","labios","chronolog","portus"],"memberAuthors":["tang-meng","guo-luanzheng","kougkas-anthony","sun-xian-he","tallent-nathan"],"funding":[{"agency":"NSF","award":"OAC-2104013","projectId":"chronolog"},{"agency":"NSF","award":"OAC-2313154","projectId":"labios"},{"agency":"PNNL","award":"DE-AC05-76RL01830"}]}')}}]);